def create_router(service, *, current_user_dependency=require_user):
    router = APIRouter(prefix='/api', tags=['conversation memory'])
    config = getattr(service, 'config', None)

    @router.post('/chat', response_model=ChatResponse)
    def chat(payload: ChatRequest, request: Request, response: Response,
             principal=Depends(current_user_dependency)):
        authorize_memory_user(payload.user_id, principal)
        try:
            context = request_context_from_headers(request.headers,
                source_commit=getattr(config, 'source_commit', None))
        except ValidationError:
            raise HTTPException(422, 'Invalid HW6 experiment headers.') from None
        response.headers['Cache-Control'] = 'no-store'
        return service.chat(payload, context=context)

    @router.get('/memory/{user_id}', response_model=MemorySnapshot,
                description='Latest 16 records in the selected/latest session, latest summaries '
                            'and last 20 user episodes. Lists oldest first.')
    def memory(user_id: str, response: Response,
               session_id: str | None = Query(None, min_length=1, max_length=200),
               principal=Depends(current_user_dependency)):
        authorize_memory_user(user_id, principal)
        response.headers['Cache-Control'] = 'no-store'
        return service.memory(user_id, session_id=session_id)

    @router.get('/aggregate/{user_id}', response_model=AggregateResponse,
                description='UTC daily counts of stored user AND assistant messages across '
                            'all user sessions; latest 10 summaries newest first.')
    def aggregate(user_id: str, response: Response, principal=Depends(current_user_dependency)):
        authorize_memory_user(user_id, principal)
        response.headers['Cache-Control'] = 'no-store'
        return service.aggregate(user_id)

    return router

def _embed(self, text, operation, context, user_id, session_id):
    started_at, timer, error, dimension = self.clock(), perf_counter(), None, None
    try:
        try:
            vector = valid_vector(self.embedder(text), self.config.embedding_dimension)
        except Exception:
            raise ModelUnavailable() from None
        dimension = len(vector)
        return vector
    except HW6Error as exc:
        error = exc
        raise
    finally:
        self._event(context, user_id, session_id, 'embedding', operation,
            started_at, timer, error=error, usage_source='not_applicable',
            input_count=1, embedding_dimension=dimension)

def extract_facts(text, user_message):
    """Reject malformed output and unsupported quotes; never ingest assistant text."""
    try:
        data = json.loads(text)
    except (ValueError, TypeError):
        return []
    if not isinstance(data, dict) or not isinstance(data.get('facts'), list):
        return []
    result, seen = [], set()
    for item in data['facts']:
        try:
            fact = ExtractedFact.model_validate(item)
        except ValidationError:
            continue
        if fact.evidence not in user_message or fact.fact.casefold() in seen:
            continue
        result.append(fact)
        seen.add(fact.fact.casefold())
        if len(result) == 3:
            break
    return result

def rank_episodes(query, episodes, *, dimension, top_k):
    unit_query = unit_vector(query, dimension)
    scored = []
    for episode in episodes:
        try:
            vector = unit_vector(episode['embedding'], dimension)
            similarity = max(-1.0, min(1.0, sum(a * b for a, b in zip(unit_query, vector))))
            scored.append(EpisodeUsed(**{key: episode[key] for key in
                ('id', 'fact', 'importance', 'created_at')}, similarity=similarity))
        except (ValueError, KeyError, TypeError):
            continue
    scored.sort(key=lambda row: (row.similarity, row.created_at, row.id), reverse=True)
    return scored[:top_k]
